# Generated by manage.py generate_test_cases.
import json

from bs4 import BeautifulSoup
from django.contrib.auth.models import Group
from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse
from django.urls import reverse
from django.utils import timezone

from bloomerp.models.tutorial import Tutorial, TutorialRevision, TutorialStep
from bloomerp.tests.base import (
    BloomerpModuleViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestMyTutorialsView(BloomerpModuleViewTestCase):
    """Tests class `MyTutorialsView` from `bloomerp/views/users/my_tutorials.py`."""

    view_name = "my_tutorials"
    module = "misc"

    def extendedSetup(self) -> None:
        """Create assigned, unassigned, and unpublished tutorials with steps."""
        for name in ("Assigned tutorial", "Unassigned tutorial", "Draft tutorial"):
            tutorial = Tutorial.objects.create(name=name, description="Learn your way around.")
            if name != "Unassigned tutorial":
                tutorial.assigned_users.add(self.normal_user)
            revision = TutorialRevision.objects.create(
                tutorial=tutorial,
                number=1,
                published_at=None if name == "Draft tutorial" else timezone.now(),
                trigger_route="home",
            )
            TutorialStep.objects.create(
                revision=revision, key="welcome", sequence=1, name="Welcome", text="Welcome"
            )
            if name == "Assigned tutorial":
                self.assigned_revision = revision

    def load_dataview(self, response: HttpResponse) -> HttpResponse:
        """Follow the shared dataview loader with its request context."""
        content_type = ContentType.objects.get_for_model(Tutorial)
        url = reverse("components_dataview", kwargs={"content_type_id": content_type.pk})
        loader = BeautifulSoup(response.content, "html.parser").select_one(
            f'div[hx-get^="{url}"][hx-trigger="load"]'
        )
        self.assertIsNotNone(loader)
        self.assertNotIn("_dataview_token=", loader["hx-get"])
        self.assertNotIn("_permission_token=", loader["hx-get"])
        return self.client.get(loader["hx-get"], headers={"HX-Request": "true", **json.loads(loader["hx-headers"])})

    def shows_assigned_tutorial(self, response: HttpResponse) -> bool:
        """Check the real dataview shows the eligible revision's Start action."""
        dataview = self.load_dataview(response)
        self.assertContains(dataview, "Assigned tutorial")
        self.assertContains(dataview, "Learn your way around.")
        self.assertNotContains(dataview, "Unassigned tutorial")
        self.assertNotContains(dataview, "Draft tutorial")
        self.assertContains(dataview, 'data-view-type="card"')
        self.assertContains(dataview, 'data-item-action-id="start-tutorial"')
        self.assertContains(
            dataview, f'data-tutorial-start-revision="{self.assigned_revision.pk}"'
        )
        return True

    def prepare_group_assignment(self, _scenario: RequestScenario) -> None:
        """Make a published tutorial available through the learner's group."""
        group = Group.objects.create(name="Tutorial learners")
        self.normal_user.groups.add(group)
        Tutorial.objects.get(name="Unassigned tutorial").assigned_groups.add(group)

    def shows_group_assignment(self, response: HttpResponse) -> bool:
        """Render the group-assigned tutorial alongside the directly assigned one."""
        dataview = self.load_dataview(response)
        self.assertContains(dataview, "Assigned tutorial")
        self.assertContains(dataview, "Unassigned tutorial")
        return True

    def removes_revoked_assignment(self, response: HttpResponse) -> bool:
        """Re-evaluate eligibility when the same signed loader is requested again."""
        self.assertContains(self.load_dataview(response), "Assigned tutorial")
        self.assigned_revision.tutorial.assigned_users.remove(self.normal_user)
        self.assertNotContains(self.load_dataview(response), "Assigned tutorial")
        return True

    def shows_empty_dataview(self, response: HttpResponse) -> bool:
        """Check the admin's wider model permissions do not add rows to My Tutorials."""
        dataview = self.load_dataview(response)
        self.assertNotContains(dataview, "Assigned tutorial")
        self.assertNotContains(dataview, "Unassigned tutorial")
        self.assertNotContains(dataview, "Draft tutorial")
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check learner access and the empty list for a user without assignments."""
        return [
            RequestScenario(
                name="A learner can list and start their assigned published tutorial",
                user=self.normal_user,
                expected=ExpectedResult(response_validators=self.shows_assigned_tutorial),
            ),
            RequestScenario(
                name="The shared dataview is empty without eligible tutorials",
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.shows_empty_dataview),
            ),
            RequestScenario(
                name="Group assignments are eligible",
                user=self.normal_user,
                prepare=self.prepare_group_assignment,
                expected=ExpectedResult(response_validators=self.shows_group_assignment),
            ),
            RequestScenario(
                name="An issued layout reflects revocations",
                user=self.normal_user,
                expected=ExpectedResult(response_validators=self.removes_revoked_assignment),
            ),
            RequestScenario(
                name="Anonymous users must sign in",
                expected=ExpectedResult(status_code=302),
            ),
        ]
